#!/usr/bin/env node
/**
 * Copy channel: every externally visible file is generated by `agy` (Gemini
 * 3.8 high) from a fact pack, never typed by the engineering agent.
 *
 *   node scripts/copy_with_agy.mjs --name readme --prompt docs/copy/prompts/readme.md --out README.md
 *   node scripts/copy_with_agy.mjs --name templates --prompt docs/copy/prompts/templates.md --split
 *
 * The raw output, the exact request hash, the facts hash and the output hash are
 * recorded in `docs/copy/manifest.json`, so a reviewer can prove which model
 * wrote which bytes. `--split` expects `<<<FILE: path>>>` markers.
 *
 * The request outgrew the Windows command line once the fact pack grew, so the
 * transport rules live in `lib/agy-channel.mjs` and are tested without a model
 * call. See the P-0007 record for the two failures that produced them.
 */

import { spawnSync } from 'node:child_process'
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { createHash } from 'node:crypto'
import { abs, isoStamp } from './lib/kit.mjs'
import {
  AGY_TIMEOUT_MS,
  buildRequest,
  cleanOutput,
  describeSpawnFailure,
  responseOf,
  stdinMessage,
  transportFor,
} from './lib/agy-channel.mjs'

const argv = process.argv.slice(2)
const flag = (name, fallback) => {
  const index = argv.indexOf(`--${name}`)
  return index === -1 ? fallback : argv[index + 1]
}
const has = (name) => argv.includes(`--${name}`)

const name = flag('name', null)
const promptPath = flag('prompt', null)
const outPath = flag('out', null)
const split = has('split')
const force = has('force')
const model = flag('model', 'gemini-3.8-flash-high')

if (name === null || promptPath === null) {
  process.stderr.write('copy_with_agy: --name and --prompt are required\n')
  process.exit(2)
}

const factsPath = 'docs/copy/facts/public-repo-facts.md'
const patternsPath = 'docs/copy/facts/oss-patterns.md'
const facts = readFileSync(abs(factsPath), 'utf8')
const patterns = readFileSync(abs(patternsPath), 'utf8')
const brief = readFileSync(abs(promptPath), 'utf8')
const request = buildRequest(brief, facts, patterns)

const agyPath = existsSync(join(process.env.LOCALAPPDATA ?? '', 'agy', 'bin', 'agy.exe'))
  ? join(process.env.LOCALAPPDATA, 'agy', 'bin', 'agy.exe')
  : 'agy'

const SPAWN_OPTIONS = {
  encoding: 'buffer',
  maxBuffer: 32 * 1024 * 1024,
  timeout: AGY_TIMEOUT_MS,
  env: { ...process.env, NO_COLOR: '1' },
}

const transport = transportFor(request)
const started = new Date().toISOString()
const run = transport === 'argv'
  ? spawnSync(agyPath, ['--model', model, '--print', request], SPAWN_OPTIONS)
  : spawnSync(
      agyPath,
      ['--model', model, '--input-format', 'stream-json', '--output-format', 'stream-json'],
      { ...SPAWN_OPTIONS, input: Buffer.from(stdinMessage(request), 'utf8') },
    )

if (run.error) {
  process.stderr.write(`copy_with_agy: could not start agy (${run.error.code ?? 'unknown'}): ${describeSpawnFailure(run.error)}\n`)
  process.exit(1)
}
if (run.status !== 0) {
  process.stderr.write(`copy_with_agy: agy exited ${run.status}\n${run.stderr?.toString('utf8') ?? ''}\n`)
  process.exit(1)
}

const transcript = run.stdout?.toString('utf8') ?? ''
const stdout = transport === 'stdin' ? responseOf(transcript) ?? '' : transcript
if (transport === 'stdin' && stdout === '') {
  process.stderr.write('copy_with_agy: agy answered without a result event\n')
  process.exit(1)
}
const cleaned = cleanOutput(stdout)
if (cleaned === '') {
  process.stderr.write('copy_with_agy: empty output\n')
  process.exit(1)
}

const rawDir = 'docs/copy/raw'
mkdirSync(abs(rawDir), { recursive: true })
writeFileSync(abs(join(rawDir, `${name}.txt`)), stdout, 'utf8')

const marker = /^<<<FILE:\s*(.+?)\s*>>>$/gm
const parts = []
if (split) {
  const matches = [...cleaned.matchAll(marker)]
  if (matches.length === 0) {
    process.stderr.write('copy_with_agy: --split but no <<<FILE: path>>> markers\n')
    process.exit(1)
  }
  for (const [index, match] of matches.entries()) {
    const start = match.index + match[0].length
    const end = index + 1 < matches.length ? matches[index + 1].index : cleaned.length
    parts.push({ target: match[1], content: cleaned.slice(start, end).trim() })
  }
} else {
  if (outPath === null) {
    process.stderr.write('copy_with_agy: --out is required without --split\n')
    process.exit(2)
  }
  parts.push({ target: outPath, content: cleaned })
}

const manifestPath = 'docs/copy/manifest.json'
const manifest = existsSync(abs(manifestPath))
  ? JSON.parse(readFileSync(abs(manifestPath), 'utf8'))
  : { schema_version: 1, model_default: model, entries: [] }
manifest.model_default = model

for (const part of parts) {
  const target = part.target.replaceAll('\\', '/')
  if (existsSync(abs(target)) && !force) {
    process.stderr.write(`copy_with_agy: refusing to overwrite ${target} (pass --force)\n`)
    process.exit(2)
  }
  const content = `${part.content}\n`
  mkdirSync(abs(join(target, '..')), { recursive: true })
  writeFileSync(abs(target), content, 'utf8')
  const entry = {
    name: parts.length === 1 ? name : `${name}:${target}`,
    target,
    model,
    generated_at: started,
    facts_sha256: createHash('sha256').update(facts).digest('hex'),
    prompt_sha256: createHash('sha256').update(brief).digest('hex'),
    request_sha256: createHash('sha256').update(request).digest('hex'),
    output_sha256: createHash('sha256').update(content).digest('hex'),
  }
  manifest.entries = manifest.entries.filter((item) => item.name !== entry.name)
  manifest.entries.push(entry)
  process.stdout.write(`WROTE ${target} (${content.length} bytes)\n`)
}

manifest.updated_at = isoStamp(new Date().toISOString())
writeFileSync(abs(manifestPath), `${JSON.stringify(manifest, null, 2)}\n`, 'utf8')
process.stdout.write(`RECORDED ${manifestPath} · ${parts.length} file(s) · model ${model} · via ${transport}\n`)
